frappe.ui.form.on("Stock Entry", {
    stock_entry_type: function(frm) {
        // First ensure the grid exists
        if (!frm.fields_dict.items?.grid) return;

        // Handle child table fields using "Stock Entry Detail" doctype
        frappe.ui.form.on("Stock Entry Detail", {
            item_code: function(frm, cdt, cdn) {
                const doc = locals[cdt][cdn];
                const is_material_issue = frm.doc.stock_entry_type === "Material Issue";
                const is_material_receipt = frm.doc.stock_entry_type === "Material Receipt";

                // Toggle visibility using toggle_display
                frm.fields_dict.items.grid.toggle_display("item_name", is_material_issue);
                frm.fields_dict.items.grid.toggle_display("item_code", is_material_receipt);
            },
            refresh_field: function(frm, cdt, cdn) {
                // Update visibility when grid refreshes
                frm.script_manager.trigger("item_code", cdt, cdn);
            }
        });

        // Trigger refresh for existing rows
        (frm.doc.items || []).forEach((row, idx) => {
            frappe.model.set_value("Stock Entry Detail", row.name, "item_code", row.item_code);
        });
    }
});

frappe.ui.form.on("Sales Invoice", {
    refresh: function (frm) {
        if (!frm.doc.__islocal) return;

        frm.add_custom_button("Send Verification Code", function () {
            if (!frm.doc.customer) {
                frappe.msgprint(__("Customer field cannot be empty. Please select a customer."));
                return;
            }

            frappe.call({
                method: "custom_reports.api.send_verification_code",
                args: {
                    customer: frm.doc.customer,
                    invoice_name: frm.doc.name
                },
                callback: function (r) {
                    if (r.message.success) {
                        frappe.msgprint("Verification code sent to customer.");
                        frm.verification_code = r.message.code;

                        function show_verification_prompt() {
                            frappe.prompt(
                                {
                                    fieldtype: "Data",
                                    label: "Enter Verification Code",
                                    fieldname: "entered_verification_code",
                                    reqd: 1
                                },
                                function (values) {
                                    frappe.call({
                                        method: "custom_reports.api.validate_verification_code",
                                        args: {
                                            invoice_name: frm.doc.name,
                                            entered_code: values.entered_verification_code
                                        },
                                        callback: function (res) {
                                            if (!res.message) {
                                                frappe.msgprint({
                                                    title: __("Error"),
                                                    indicator: "red",
                                                    message: __("Incorrect verification code. Please try again.")
                                                });
                                                show_verification_prompt(); // Reopen the prompt if wrong
                                            } else {
                                                frappe.msgprint("Verification successful! You can now submit the invoice.");
                                                frm.verification_confirmed = true;
                                            }
                                        }
                                    });
                                },
                                "Verification Required",
                                "Verify"
                            );
                        }

                        show_verification_prompt(); // Open the prompt initially
                    }
                }
            });
        });
    },

    validate: function (frm) {
        if (!frm.verification_confirmed) {
            frappe.throw("You must verify the invoice before submitting.");
        }
    }
});
